class Trip {
  constructor(destination, miles, gallons) {
    this.destination = destination;
    this.miles = miles;
    this.gallons = gallons;
  }
  get mpg() {
    return Number((this.miles / this.gallons).toFixed(1));
  }
  toString() {
    return `${this.destination}: ${this.mpg} mpg`;
  }
}

class RoadTrip extends Trip {
  constructor(destination, miles, gallons, stops) {
    super(destination, miles, gallons);
    this.stops = stops;
  }
  toString() {
    return `${super.toString()} (${this.stops} stops)`;
  }
}

const createCounter = (start = 0) => {
  let count = start;
  return {
    increment() {
      count++;
      return count;
    },
    reset() {
      count = start;
    },
    getCount() {
      return count;
    },
  };
};

tests.code:
